INSERT INTO `PERF_METRIC_DEF` (`id`, `metric_code`, `metric_name`, `metric_name_en`, `metric_desc`, `base_dim`, `metric_level`, `calc_freq`, `calc_mode`, `calc_logic_type`, `sql_text`, `expr_text`, `summary_rule`, `ref_metric_codes`, `val_slot`, `unit`, `decimal_places`, `deleted`, `description`, `metric_category`, `status`, `created_by`, `created_time`, `updated_by`, `updated_time`, `cron_expr`, `subject_sql`, `last_run_time`) VALUES ('0257368950484b2f8cbc12b3aeef6ea1','M_0077','零售结算性存款年日均-员工',NULL,NULL,'EMP',1,'DAY','AUTO','SQL','select t2.emp_id as base_key, sum(t1.curr_bal*t2.ratio/100) as metric_value \nfrom XAN_M98_CUST_STAT_SHOW3 t1\ninner join \n(\n    SELECT *,\n        ROW_NUMBER() OVER(PARTITION BY emp_id ORDER BY effective_date DESC) AS rn\n    FROM CUST_ALLOC_RELATION \n		where effective_date<=:allocDate\n) t2\non t1.CUST_ID=t2.cust_id and t2.rn = 1\nwhere t1.STATIS_DT=:dataDate\ngroup by t2.emp_id',NULL,'SUM','[]',40,NULL,2,0,NULL,'效益类','ACTIVE','E40001','2026-05-18 13:32:02','E40001','2026-06-18 10:41:41',NULL,NULL,NULL);
